<script setup>
import {ref,watch} from 'vue'
import {api,openWorkspace} from '../api.js'
import {Accordion,AccordionItem,AccordionTrigger,AccordionContent,Badge,Button,Spinner} from '../../shared/shadcn-ui.js'
const props=defineProps({workItemId:Number}),items=ref([]),loading=ref(false),error=ref(''),cursor=ref(0);let seq=0
async function load(more=false){const n=++seq;loading.value=true;error.value='';try{const q=new URLSearchParams({work_item_id:props.workItemId});if(more&&cursor.value)q.set('before_id',cursor.value);const v=await api('api-documents/work-item-changes?'+q);if(n!==seq)return;items.value=more?[...items.value,...v.items]:v.items;cursor.value=v.next_before_id}catch(e){if(n===seq)error.value=e.message}finally{if(n===seq)loading.value=false}}
watch(()=>props.workItemId,()=>{items.value=[];cursor.value=0;load()},{immediate:true})
function open(item,event,comparison=false){const q=new URLSearchParams({service:item.service,environment:item.environment,snapshot:item.snapshot_id,work_item:props.workItemId});if(comparison){q.set('tab','history');q.set('base_id',item.baseline_id)}else if(event)q.set('operation',event.operation);openWorkspace('api-center','#/documents?'+q)}
</script>
<template><section class="col-span-full min-w-0 space-y-4" aria-label="需求接口变更"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="text-lg font-semibold">接口与字段变更</h3><Button variant="outline" :disabled="loading" @click="load()"><Spinner v-if="loading"/>刷新</Button></div><div v-if="error" class="space-y-2"><p class="text-sm text-destructive">{{error}}</p><Button variant="outline" @click="load()">重试</Button></div><p v-else-if="!items.length&&!loading" class="rounded-lg border p-8 text-center text-sm text-muted-foreground">此需求还没有关联的接口修订。编辑文档时关联本需求，保存后即可在此核对新增、修改和删除的字段；未关联历史不推断补写。</p><section v-for="item in items" :key="item.snapshot_id" class="min-w-0 rounded-lg border p-4"><div class="mb-3 flex flex-wrap items-center gap-2"><Badge variant="outline">{{item.service}} · {{item.environment}}</Badge><span class="text-sm">基线 #{{item.baseline_id||'无'}} → 修订 #{{item.snapshot_id}}</span><Button variant="link" @click="open(item,null,true)">版本对比</Button></div><Accordion type="multiple"><AccordionItem v-for="event in item.events" :key="event.key" :value="event.key"><AccordionTrigger class="text-left"><span class="min-w-0 break-all">{{({added:'新增',modified:'修改',removed:'删除',unavailable:'字段分析未完成'})[event.change]}} · {{event.operation}}<span v-if="event.field"> · {{event.field.in}} · {{event.field.name}}</span></span></AccordionTrigger><AccordionContent class="space-y-3"><div class="grid min-w-0 gap-3 md:grid-cols-2"><div><p class="mb-1 text-xs text-muted-foreground">变更前</p><pre class="max-h-48 max-w-full overflow-auto rounded-md bg-muted p-3 text-xs">{{event.change==='added'?'（新增前不存在）':event.before||'（定义过大，请查看版本对比）'}}</pre></div><div><p class="mb-1 text-xs text-muted-foreground">变更后</p><pre class="max-h-48 max-w-full overflow-auto rounded-md bg-muted p-3 text-xs">{{event.change==='removed'?'（已删除）':event.definition||'（定义过大，请查看版本对比）'}}</pre></div></div><Button variant="outline" @click="open(item,event)">{{event.change==='removed'?'查看该修订':'打开接口'}}</Button></AccordionContent></AccordionItem></Accordion></section><Button v-if="cursor" variant="outline" :disabled="loading" @click="load(true)"><Spinner v-if="loading"/>更多修订</Button></section></template>
